    /*
     * Add to the Items
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Cart
     */
    public Cart addToItems( UUID parentId, CartItem addTo ) {
	    LOGGER.info("handling AssignItemsToCartEvent - " );
	    
	    Cart parentEntity = repository.findById(parentId).get();
	    CartItem child = registry.project( CartItem.class, addTo.getCartItemId());
	    
	    parentEntity.getItems().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Items
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Cart
     */
	public Cart removeFromItems( UUID parentId, CartItem removeFrom ) {
	    LOGGER.info("handling RemoveItemsFromCartEvent " );
	
	    Cart parentEntity = repository.findById(parentId).get();
	    CartItem child = registry.project( CartItem.class, removeFrom.getCartItemId());
	    
	    parentEntity.getItems().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

    /*
     * Add to the AppliedPromotions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Cart
     */
    public Cart addToAppliedPromotions( UUID parentId, Promotion addTo ) {
	    LOGGER.info("handling AssignAppliedPromotionsToCartEvent - " );
	    
	    Cart parentEntity = repository.findById(parentId).get();
	    Promotion child = registry.project( Promotion.class, addTo.getPromotionId());
	    
	    parentEntity.getAppliedPromotions().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the AppliedPromotions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Cart
     */
	public Cart removeFromAppliedPromotions( UUID parentId, Promotion removeFrom ) {
	    LOGGER.info("handling RemoveAppliedPromotionsFromCartEvent " );
	
	    Cart parentEntity = repository.findById(parentId).get();
	    Promotion child = registry.project( Promotion.class, removeFrom.getPromotionId());
	    
	    parentEntity.getAppliedPromotions().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Cart via an FindCartQuery
     * @return 	query	FindCartQuery
     */
    @SuppressWarnings("unused")
    public Cart find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Cart - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Carts
     *
     * @param	query	FindAllCartQuery 
     * @return 	List<Cart> 
     */
    @SuppressWarnings("unused")
    public List<Cart> findAll( FindAllCartQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Cart - {0}", exc.getMessage() );
    	}
    	return null;
    }


